from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from oauth2_provider.models import AccessToken

class BatchTokenIntrospectView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def post(self, request):
        token_list = request.data.get("tokens", [])
        caller_app = getattr(request.auth, 'application', None)
        # Limit token resolution to tokens issued for the caller's registered application
        tokens = AccessToken.objects.filter(
            token__in=token_list,
            application=caller_app
        ).values(
            "token", "scope", "application__name", "user__username"
        )
        results = {t["token"]: t for t in tokens}
        return Response({"resolved_tokens": results}, status=status.HTTP_200_OK)
